import React from 'react';

export default function Navbar({ email, onLogout }) {
  return (
    <header style={{ padding: '12px 18px' }}>
      <div className="container" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div className="logo">
          <div className="mark">B</div>
          <div>
            <div style={{ fontSize: 14, opacity: 0.9 }}>BestOdds</div>
            <div style={{ fontSize: 11, opacity: 0.7, marginTop: -2 }}>GH</div>
          </div>
        </div>

        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <div style={{ opacity: 0.9, color: 'var(--muted)' }}>{email}</div>
          <button className="btn" onClick={onLogout}>Logout</button>
        </div>
      </div>
    </header>
  );
}
